import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";

const rootElement = document.getElementById("app");
if (rootElement) {
  ReactDOM.createRoot(rootElement).render(
    <React.StrictMode>
      <App />
    </React.StrictMode>,
  );
}

import("./snHttpTest")
  .then((module) => {
    console.log("dynamic import successful, time to make a request");
    module.default();
  })
  .catch((err) => {
    console.error("Failed to load snHttpTest module:", err);
  });

const hello = () => console.log("Hello, NowSDK!");

export { hello };
